  const schema = { "@context": "https://schema.org", "@type": "SoftwareApplication", name: "KinForge Genealogy Studio", applicationCategory: "LifestyleApplication", operatingSystem: "macOS, Windows, Web", softwareVersion: release.version, url: `${siteOrigin}/website/`, downloadUrl: `${siteOrigin}/downloads`, description: "Relationship mapping, family trees, genograms, character records, history projects and story-world continuity for social workers, writers, genealogists, historians, roleplayers and RPG players.", publisher: { "@type": "Organization", name: "Dreams of Serene Landscapes" } };
