const heading = (eyebrow: string, title: string, text: string) => `<section class="page-heading wrap"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${text}</p></section>`;
const exportTerms = `<div class="notice"><strong>KinForge copyright and export terms.</strong> Copyright 2026 Dreams of Serene Landscapes. All rights reserved. Free trials, KinForge Genealogy Studio Suite, beta access, and approved KinForge Genealogy Special Access Edition access all keep the KinForge credit and Dreams of Serene Landscapes copyright on app exports and downloads. Extra written permission or Special Access Edition approval must be requested through support with real, non-AI proof such as photos together or other digital or physical records.</div>`;
const appDescription = `<section class="wrap section prose"><h2>Why KinForge exists</h2><p>KinForge Genealogy Studio was created by Dreams of Serene Landscapes after months of trying other genealogy and relationship-mapping tools and finding that many were too limited, too rigid, or priced beyond what many users could reasonably afford.</p><p>Dreams of Serene Landscapes built KinForge with a mission to make genealogy, genograms, family history, fictional lineages, historical networks, and worldbuilding more accessible, inclusive, and practical. KinForge is designed to offer the features people actually need, with more affordable paths for writers, social workers, genealogists, historians, roleplayers, RPG players, educators, students, nonprofits, and everyday families.</p><h2>Their Story</h2><p>KinForge began when Dreams of Serene Landscapes spent months trying to make existing genealogy and relationship tools work for real needs: family history, complicated relationships, creative worlds, records, reports, accessibility, and affordability. The available options often felt too narrow, too expensive, or not built for the people who needed them most.</p><p>Instead of accepting those limits, Dreams of Serene Landscapes chose to build a new kind of relationship studio: one that could respect genealogy while also serving social workers, writers, historians, roleplayers, RPG players, students, educators, nonprofits, and families. KinForge is their answer to the belief that people deserve better tools for understanding where they come from, who they are connected to, and the stories they are trying to preserve or create.</p><h2>Mission</h2><p>To give people a fairer, clearer, and more capable way to understand relationships, preserve stories, map communities, and build worlds without being blocked by inaccessible tools or unreasonable pricing.</p><h2>Vision</h2><p>A world where family history, care context, historical memory, fictional continuity, and creative worldbuilding are easier to protect, understand, and share responsibly.</p><h2>Values</h2><ul><li><strong>Accessibility:</strong> make KinForge accessible to as many people as possible, including people with special needs, disabilities, and different ways of learning or working.</li><li><strong>Affordable pricing:</strong> offer fairer paths for people who need genealogy and relationship tools without unreasonable plan costs.</li><li><strong>Genealogy matters:</strong> bring light to the importance of genealogy, family history, identity, cultural memory, and the stories that connect people across generations.</li><li><strong>Inclusivity:</strong> support many kinds of relationship work, including families, care networks, histories, fiction, roleplay, and RPG worlds.</li><li><strong>User ownership:</strong> help users keep control of their accounts, exports, backups, and creative or research work.</li><li><strong>Respectful records:</strong> treat real people, sensitive information, and private histories with care.</li><li><strong>Better tools:</strong> keep improving features that existing services often leave unfinished, overpriced, or too narrow.</li></ul><p>Subscriptions help keep KinForge improving, support future releases, and move the project toward a better, more accessible relationship-mapping tool for everyone, one step at a time.</p></section>`;
const planSummary = `<h3>Subscription tiers</h3><p>The paid subscription app name is <strong>KinForge Genealogy Studio Suite</strong>. Paid Suite subscriptions are <strong>Basic</strong>, <strong>Plus</strong>, <strong>Premium</strong>, and <strong>Pro</strong>, and can be offered weekly, monthly, or yearly.</p><section class="feature-columns"><article><h3>Free trial</h3><p>Includes the 4-day free trial, separate demo, simplified relationship map, basic profiles, basic exports, and a lower-capacity way to test whether KinForge fits the user's work.</p><a class="button secondary" href="/downloads/trial">Download trial</a></article><article><h3>Basic</h3><p>The entry paid Suite plan for users who want to keep using KinForge after the trial with steadier workspace access, better saving flow, and less limited everyday tools than the free trial.</p><a class="button secondary" href="/downloads/paid">Basic Suite</a></article><article><h3>Plus</h3><p>Good for individual family projects, writers, students, roleplayers, and small research files. Adds more saved work, cleaner exports, better organization, and fuller profile/report tools than Basic.</p><a class="button secondary" href="/downloads/paid">Plus Suite</a></article><article><h3>Premium</h3><p>Good for serious genealogists, historians, educators, social workers, campaign managers, and larger story worlds. Adds deeper records, richer reports, larger libraries, more export options, and stronger project organization.</p><a class="button secondary" href="/downloads/paid">Premium Suite</a></article><article><h3>Pro</h3><p>Best for heavy professional, nonprofit, education, author, research, and long-term archive work. Adds the highest Suite limits, priority feature consideration, advanced reports, stronger backup/export workflows, and beta-preview access when available.</p><a class="button secondary" href="/downloads/paid">Pro Suite</a></article></section><h3>Payment cadence</h3><ul><li>Weekly Suite plan: best for short projects, one-off reports, class assignments, or temporary campaign planning.</li><li>Monthly Suite plan: best for steady use across genealogy, writing, social-work, history, education, roleplay, or nonprofit work.</li><li>Yearly Suite plan: best long-term value for ongoing archives, large family projects, professional files, and big fictional worlds.</li></ul><h3>Discount codes and rates</h3><ul><li>Writers: WRITERFORGE20 - 20% off.</li><li>DND players: DNDFORGE20 - 20% off.</li><li>Roleplayers: ROLEPLAYFORGE20 - 20% off.</li><li>RPG players: RPGFORGE20 - 20% off.</li><li>Historians: HISTORYFORGE25 - 25% off.</li><li>Genealogists: GENEALOGYFORGE25 - 25% off.</li><li>Social workers: SOCIALCARE30 - 30% off.</li><li>Students: STUDENTFORGE35 - 35% off.</li><li>Nonprofits: NONPROFITFORGE40 - 40% off.</li><li>Educators: EDUFORGE30 - 30% off.</li><li>Other users: standard payment applies.</li></ul><p>New account setup asks what kind of user someone is. If they choose Other, they use the standard payment path.</p><h3>Beta program</h3><p>Joining the beta program gives early access to preview builds, a sandbox testing path, update notices, and a way to send feedback before changes become stable. Beta builds can contain bugs, so users should test with copies and keep backups.</p><h3>KinForge Genealogy Special Access Edition</h3><p>The Special Access Edition is for approved close or special people only. They can request it through support and, if approved, use the special download page with a code. The KinForge/Dreams copyright and credit still apply.</p>`;
