const home = `${heading("Relationship maps for families, cases, history and story worlds", "KinForge Genealogy Studio", "Download KinForge, create a free account, or start the 4-day free trial before choosing a Suite plan or requesting special access.")}<div class="actions"><a class="button" href="/downloads">Download KinForge</a><a class="button secondary" href="/#/create-account">Create free account</a><a class="button secondary" href="/">Get started free</a><a class="button secondary" href="/website/beta/">Plans</a></div><figure class="product-shot wrap"><img src="/website/chart-desktop.png" width="1440" height="960" alt="KinForge demo relationship tree with connected generations and a person details panel"><figcaption>A fictional family in the separate guest demo. No account required.</figcaption></figure>${appDescription}<section class="band"><div class="wrap"><p class="eyebrow">Our mission</p><h2>Know the people. Understand the connections.</h2><p class="lead">KinForge is made for relationship-rich work: family history, social-work genograms, fictional casts, historical networks, tabletop campaigns, RPG worlds and long-running story continuity.</p><p>Use it for family historians, social workers, writers, fantasy and mythology builders, illustrators, roleplayers, DND and RPG players, historians, researchers, and anyone who wants to understand how people, worlds and generations connect.</p><div class="feature-columns"><article><h3>Free trial first</h3><p>New users can try simplified, lower-quality access for four days before choosing a plan or requesting special access.</p></article><article><h3>Across projects</h3><p>Keep books, cases, collections, subcollections, campaigns and trees together in your library.</p></article><article><h3>Beyond names</h3><p>Bring biographies, facts, events, sources, sensitive notes, character notes and case context into one place.</p></article></div><a href="/website/features/">Explore the workspace &rarr;</a></div></section><section class="wrap section"><h2>Start with a person. Open up a network.</h2><p>Try KinForge in a browser or download the Mac and Windows app. Explore the demo, then create a KinForge account for your private cloud library.</p><div class="actions left"><a class="button" href="/downloads/trial">Download trial</a><a class="button secondary" href="/website/tutorials/">Watch tutorials</a><a class="button secondary" href="/downloads/special-access">Special access</a></div></section>`;
const officialApp = `${heading("Official KinForge app", "Use KinForge in the browser, on Mac, or on Windows", "This is the official app page for KinForge Genealogy Studio, a product of Dreams of Serene Landscapes for social workers, writers, genealogists, historians, roleplayers, RPG players and more.")}<section class="wrap section prose">${exportTerms}<h2>How to use the app</h2><p><a href="/">Open the web app</a> for the quickest start, or use the desktop downloads for Mac and Windows. New users may start with a 4-day free trial that has simplified, lower-quality access to the core tools.</p><h2>Who KinForge is for</h2><p>KinForge is for social workers mapping relationships and care context, writers building casts and series continuity, genealogists researching family lines, historians tracking people and evidence, roleplayers and RPG players managing campaigns, and anyone who needs a clear relationship chart with notes, sources and reports.</p><h2>KinForge account sign-in</h2><p>Accounts use KinForge email and password sign-in. They do not use ChatGPT login. Store your recovery key safely after creating an account.</p><h2>Desktop downloads</h2><p>The download page includes free trial, paid, and special-edition paths for Apple Silicon Mac, Intel Mac and Windows packages. Checksums are listed beside each file.</p><p><a class="button" href="/downloads">Download the official app</a></p><h2>Beta version</h2><p>The beta and plans page explains tier benefits, user-type discounts, the 4-day trial, and how to request special access if the unpaid full-feature version is appropriate.</p><p><a href="/website/beta/">View plans and beta access</a></p><h2>Tutorials</h2><p>The tutorial page includes captioned walkthrough videos and transcripts for the demo, person profiles, reports and library workflow.</p><p><a href="/website/tutorials/">Open tutorials</a></p></section>`;
